  `deposit_paid_at` DATETIME COMMENT '定金支付时间',
  `balance_start_at` DATETIME COMMENT '尾款开始时间',
  `balance_end_at` DATETIME COMMENT '尾款截止时间',
  `deposit_expand` DECIMAL(14,2) COMMENT '定金膨胀金额',
  `status` VARCHAR(64) COMMENT '预售状态：DEPOSIT_PAID/BALANCE_PAID/EXPIRED',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='预售订单定金与尾款';

DROP TABLE IF EXISTS `trd_order_source`;
CREATE TABLE `trd_order_source` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '来源ID',
  `code` VARCHAR(64) COMMENT '来源编码：APP/MINI_PROGRAM/WEB/LIVE/OFFLINE',
  `name` VARCHAR(64) COMMENT '来源名称',
  `is_online` TINYINT COMMENT '是否线上',
  `sort_order` INT COMMENT '排序',
  `owner_team` VARCHAR(64) COMMENT '负责团队',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单来源维表';

DROP TABLE IF EXISTS `trd_daily_shop_sales`;
CREATE TABLE `trd_daily_shop_sales` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `stat_date` DATE COMMENT '统计日期',
  `shop_id` BIGINT COMMENT '店铺ID',
  `gmv` DECIMAL(14,2) COMMENT 'GMV：当日支付订单的商品总额+运费，不扣优惠、不扣退款',
  `paid_amount` DECIMAL(14,2) COMMENT '实付金额：当日支付订单的实付合计',
  `refund_amount` DECIMAL(14,2) COMMENT '当日退款成功金额',
  `net_sales` DECIMAL(14,2) COMMENT '退款后金额=实付金额-退款金额',
  `order_cnt` INT COMMENT '支付订单数',
  `buyer_cnt` INT COMMENT '支付买家数',
  `discount_amount` DECIMAL(14,2) COMMENT '当日优惠总额',
  `freight_amount` DECIMAL(14,2) COMMENT '当日运费',
  `new_buyer_cnt` INT COMMENT '新买家数',
  `item_qty` INT COMMENT '销售件数',
  `refund_order_cnt` INT COMMENT '退款订单数',
  `cancel_order_cnt` INT COMMENT '取消订单数',
  `etl_batch` VARCHAR(64) COMMENT 'ETL批次号',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_stat_date` (`stat_date`),
  KEY `idx_shop_id` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='店铺日销售汇总（T+1离线计算）';

DROP TABLE IF EXISTS `trd_daily_sku_sales`;
CREATE TABLE `trd_daily_sku_sales` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `stat_date` DATE COMMENT '统计日期',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `sales_qty` INT COMMENT '销量件数',
  `sales_amount` DECIMAL(14,2) COMMENT '销售额（实付分摊口径）',
  `refund_qty` INT COMMENT '退款件数',
  `shop_id` BIGINT COMMENT '店铺ID（汇总为全店铺时为空）',
  `gmv` DECIMAL(14,2) COMMENT 'SKU维度GMV',
  `order_cnt` INT COMMENT '包含该SKU的订单数',
  `buyer_cnt` INT COMMENT '买家数',
  `refund_amount` DECIMAL(14,2) COMMENT '退款金额',
  `etl_batch` VARCHAR(64) COMMENT 'ETL批次号',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_stat_date` (`stat_date`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU日销售汇总（T+1离线计算）';

DROP TABLE IF EXISTS `trd_order_cancel`;
CREATE TABLE `trd_order_cancel` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `order_id` BIGINT COMMENT '订单ID',
  `cancel_reason` VARCHAR(64) COMMENT '取消原因',
  `cancel_by` VARCHAR(64) COMMENT '发起方：USER/SYSTEM_TIMEOUT/CS',
  `cancelled_at` DATETIME COMMENT '取消时间',
  `refund_needed` TINYINT COMMENT '是否需要退款',
  `order_status_before` VARCHAR(64) COMMENT '取消前状态：CREATED/PAID',
  `remark` VARCHAR(255) COMMENT '备注',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单取消记录';

DROP TABLE IF EXISTS `trd_complaint`;
CREATE TABLE `trd_complaint` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `order_id` BIGINT COMMENT '订单ID',
  `complaint_type` VARCHAR(64) COMMENT '客诉类型：LOGISTICS/QUALITY/SERVICE/PRICE',
  `severity` TINYINT COMMENT '严重程度1-3',
  `created_at` DATETIME COMMENT '创建时间',
  `resolved_at` DATETIME COMMENT '解决时间',
  `complaint_no` VARCHAR(64) COMMENT '工单号',
  `channel` VARCHAR(64) COMMENT '客诉渠道：PHONE/ONLINE/12315/SOCIAL',
  `handler` VARCHAR(64) COMMENT '处理人',
  `result` VARCHAR(64) COMMENT '处理结果：COMPENSATED/EXPLAINED/ESCALATED',
  `satisfaction` TINYINT COMMENT '满意度1-5',
  `is_escalated` TINYINT COMMENT '是否升级',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客诉工单';

DROP TABLE IF EXISTS `trd_return_logistics`;
CREATE TABLE `trd_return_logistics` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `refund_id` BIGINT COMMENT '退款单ID',
  `carrier_id` BIGINT COMMENT '承运商ID',
  `tracking_no` VARCHAR(64) COMMENT '退货运单号',
  `shipped_at` DATETIME COMMENT '用户寄出时间',
  `received_at` DATETIME COMMENT '仓库签收时间',
  `freight_fee` DECIMAL(14,2) COMMENT '退货运费',
  `freight_payer` VARCHAR(64) COMMENT '运费承担方：BUYER/MERCHANT/INSURANCE',
  `warehouse_id` BIGINT COMMENT '退回仓库ID',
  `inspect_result` VARCHAR(64) COMMENT '质检结果：PASS/DAMAGED/MISSING',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_refund_id` (`refund_id`),
  KEY `idx_carrier_id` (`carrier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退货物流：用户寄回商品的运单';

DROP TABLE IF EXISTS `trd_compensation`;
CREATE TABLE `trd_compensation` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '赔付ID',
  `order_id` BIGINT COMMENT '订单ID',
  `comp_type` VARCHAR(64) COMMENT '赔付类型：CASH/COUPON/POINTS',
  `amount` DECIMAL(14,2) COMMENT '赔付金额',
  `reason_code` VARCHAR(64) COMMENT '原因编码',
  `created_at` DATETIME COMMENT '赔付时间',
  `comp_no` VARCHAR(64) COMMENT '赔付单号',
  `approved_by` VARCHAR(64) COMMENT '审批人',
  `status` VARCHAR(64) COMMENT '状态：APPLIED/PAID/REJECTED',
  `paid_at` DATETIME COMMENT '发放时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_reason_code` (`reason_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='赔付单：对用户的额外补偿';

DROP TABLE IF EXISTS `trd_order_tag`;
CREATE TABLE `trd_order_tag` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `order_id` BIGINT COMMENT '订单ID',
  `tag` VARCHAR(64) COMMENT '标签：FIRST_ORDER首单/BIG_PROMO大促/HIGH_RISK风险单',
  `tag_source` VARCHAR(64) COMMENT '打标来源：RULE/MODEL/MANUAL',
  `tagged_at` DATETIME COMMENT '打标时间',
  `expire_at` DATETIME COMMENT '失效时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='订单标签';

DROP TABLE IF EXISTS `trd_gift_card_usage`;
CREATE TABLE `trd_gift_card_usage` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `order_id` BIGINT COMMENT '订单ID',
  `card_no` VARCHAR(64) COMMENT '礼品卡号',
  `used_amount` DECIMAL(14,2) COMMENT '抵扣金额',
  `used_at` DATETIME COMMENT '使用时间',
  `card_type` VARCHAR(64) COMMENT '卡类型：ELECTRONIC/PHYSICAL',
  `card_face_value` DECIMAL(14,2) COMMENT '卡面额',
  `balance_after` DECIMAL(14,2) COMMENT '使用后余额',
  `member_id` BIGINT COMMENT '会员ID',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='礼品卡使用记录';

DROP TABLE IF EXISTS `prd_spu`;
CREATE TABLE `prd_spu` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT 'SPU ID',
  `spu_name` VARCHAR(255) COMMENT '商品名称',
  `category_id` BIGINT COMMENT '末级类目ID',
  `brand_id` BIGINT COMMENT '品牌ID',
  `series_id` BIGINT COMMENT '系列ID',
  `launch_date` DATE COMMENT '首次上架日期',
  `spu_code` VARCHAR(64) COMMENT 'SPU编码',
  `subtitle` VARCHAR(255) COMMENT '副标题',
  `origin` VARCHAR(64) COMMENT '产地',
  `shelf_life_days` INT COMMENT '保质期（天）',
  `is_imported` TINYINT COMMENT '是否进口',
  `tax_rate` DECIMAL(12,6) COMMENT '税率',
  `spu_status` VARCHAR(64) COMMENT '状态：ON_SALE/OFF_SALE/DRAFT',
  `main_image` VARCHAR(255) COMMENT '主图URL',
  `selling_point` VARCHAR(255) COMMENT '卖点',
  `season` VARCHAR(64) COMMENT '适用季节：SPRING/SUMMER/AUTUMN/WINTER/ALL',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_brand_id` (`brand_id`),
  KEY `idx_series_id` (`series_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品SPU：同款商品';

DROP TABLE IF EXISTS `prd_sku`;
CREATE TABLE `prd_sku` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT 'SKU ID',
  `spu_id` BIGINT COMMENT 'SPU ID',
  `sku_code` VARCHAR(64) COMMENT 'SKU编码',
  `spec` VARCHAR(255) COMMENT '规格描述，如颜色/尺码',
  `list_price` DECIMAL(14,2) COMMENT '标价',
  `status` VARCHAR(64) COMMENT '状态：ON_SALE在售/OFF_SALE下架',
  `barcode` VARCHAR(64) COMMENT '主条码',
  `weight_kg` DECIMAL(14,2) COMMENT '重量（千克）',
  `volume_cm3` DECIMAL(14,2) COMMENT '体积（立方厘米）',
  `color` VARCHAR(64) COMMENT '颜色',
  `size` VARCHAR(64) COMMENT '尺码',
  `market_price` DECIMAL(14,2) COMMENT '市场价',
  `min_order_qty` INT COMMENT '起订量',
  `is_fragile` TINYINT COMMENT '是否易碎',
  `image` VARCHAR(255) COMMENT '图片URL',
  `launch_at` DATETIME COMMENT '上架时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_spu_id` (`spu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品SKU：可售卖的最小单元（规格）';

DROP TABLE IF EXISTS `prd_category`;
CREATE TABLE `prd_category` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '类目ID',
  `parent_id` BIGINT COMMENT '父类目ID，一级类目为0',
  `level` TINYINT COMMENT '层级1/2/3',
  `name` VARCHAR(64) COMMENT '类目名称',
  `code` VARCHAR(64) COMMENT '类目编码',
  `sort_order` INT COMMENT '排序',
  `is_leaf` TINYINT COMMENT '是否末级',
  `icon` VARCHAR(255) COMMENT '图标URL',
  `gross_margin_target` DECIMAL(12,6) COMMENT '目标毛利率',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_parent_id` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品类目，三级树形';

DROP TABLE IF EXISTS `prd_brand`;
CREATE TABLE `prd_brand` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '品牌ID',
  `name` VARCHAR(64) COMMENT '品牌名称',
  `is_own` TINYINT COMMENT '是否自有品牌',
  `country` VARCHAR(64) COMMENT '品牌国家',
  `english_name` VARCHAR(64) COMMENT '英文名',
  `logo` VARCHAR(255) COMMENT 'Logo URL',
  `level` VARCHAR(64) COMMENT '品牌等级：S/A/B/C',
  `authorized_until` DATE COMMENT '授权截止日期',
  `contact` VARCHAR(64) COMMENT '品牌对接人',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='品牌';

DROP TABLE IF EXISTS `prd_price_history`;
CREATE TABLE `prd_price_history` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `old_price` DECIMAL(14,2) COMMENT '原价格',
  `new_price` DECIMAL(14,2) COMMENT '新价格',
  `changed_at` DATETIME COMMENT '变更时间',
  `change_reason` VARCHAR(64) COMMENT '调价原因：PROMOTION/COST_CHANGE/COMPETITOR/CLEARANCE',
  `operator` VARCHAR(64) COMMENT '操作人',
  `approved` TINYINT COMMENT '是否审批通过',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU价格变更历史';

DROP TABLE IF EXISTS `prd_attribute`;
CREATE TABLE `prd_attribute` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '属性ID',
  `name` VARCHAR(64) COMMENT '属性名，如颜色/材质',
  `category_id` BIGINT COMMENT '适用类目ID',
  `input_type` VARCHAR(64) COMMENT '录入方式：SELECT/TEXT/NUMBER',
  `is_required` TINYINT COMMENT '是否必填',
  `is_searchable` TINYINT COMMENT '是否可搜索',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品属性定义';

DROP TABLE IF EXISTS `prd_sku_attribute`;
CREATE TABLE `prd_sku_attribute` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `attribute_id` BIGINT COMMENT '属性ID',
  `value` VARCHAR(64) COMMENT '属性值',
  `value_code` VARCHAR(64) COMMENT '属性值编码',
  `sort_order` INT COMMENT '排序',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`),
  KEY `idx_attribute_id` (`attribute_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU属性取值';

DROP TABLE IF EXISTS `prd_label`;
CREATE TABLE `prd_label` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '标签ID',
  `name` VARCHAR(64) COMMENT '标签名，如新品/爆款/清仓',
  `label_type` VARCHAR(64) COMMENT '标签类型：OPERATION/SYSTEM',
  `color` VARCHAR(64) COMMENT '显示颜色',
  `is_active` TINYINT COMMENT '是否启用',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品标签定义';

DROP TABLE IF EXISTS `prd_sku_label`;
CREATE TABLE `prd_sku_label` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `label_id` BIGINT COMMENT '标签ID',
  `start_at` DATETIME COMMENT '生效时间',
  `end_at` DATETIME COMMENT '失效时间',
  `operator` VARCHAR(64) COMMENT '打标人',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`),
  KEY `idx_label_id` (`label_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU打标';

DROP TABLE IF EXISTS `prd_bundle`;
CREATE TABLE `prd_bundle` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '套装ID',
  `name` VARCHAR(255) COMMENT '套装名称',
  `bundle_price` DECIMAL(14,2) COMMENT '套装价',
  `status` VARCHAR(64) COMMENT '状态：ON_SALE/OFF_SALE',
  `start_at` DATETIME COMMENT '开始时间',
  `end_at` DATETIME COMMENT '结束时间',
  `shop_id` BIGINT COMMENT '店铺ID',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='组合套装';

DROP TABLE IF EXISTS `prd_bundle_item`;
CREATE TABLE `prd_bundle_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `bundle_id` BIGINT COMMENT '套装ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `quantity` INT COMMENT '件数',
  `is_main` TINYINT COMMENT '是否主商品',
  `share_ratio` DECIMAL(12,6) COMMENT '价格分摊比例',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_bundle_id` (`bundle_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='套装包含的SKU';

DROP TABLE IF EXISTS `prd_listing_log`;
CREATE TABLE `prd_listing_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `action` VARCHAR(64) COMMENT '动作：ON/OFF',
  `acted_at` DATETIME COMMENT '操作时间',
  `shop_id` BIGINT COMMENT '店铺ID',
  `operator` VARCHAR(64) COMMENT '操作人',
  `reason` VARCHAR(64) COMMENT '原因：NEW/RESTOCK/SOLD_OUT/COMPLIANCE/SEASON_END',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='上下架记录';

DROP TABLE IF EXISTS `prd_sku_cost`;
CREATE TABLE `prd_sku_cost` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `month_key` VARCHAR(64) COMMENT '月份YYYY-MM',
  `unit_cost` DECIMAL(14,2) COMMENT '单位成本',
  `supplier_id` BIGINT COMMENT '主供应商ID',
  `freight_cost` DECIMAL(14,2) COMMENT '单位运输成本',
  `cost_source` VARCHAR(64) COMMENT '成本来源：PURCHASE/ESTIMATE',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU采购成本（按月）';

DROP TABLE IF EXISTS `prd_series`;
CREATE TABLE `prd_series` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '系列ID',
  `brand_id` BIGINT COMMENT '品牌ID',
  `name` VARCHAR(64) COMMENT '系列名称',
  `launch_year` INT COMMENT '上市年份',
  `positioning` VARCHAR(64) COMMENT '定位：ENTRY/MID/PREMIUM',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_brand_id` (`brand_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品系列';

DROP TABLE IF EXISTS `prd_sku_barcode`;
CREATE TABLE `prd_sku_barcode` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `barcode` VARCHAR(64) COMMENT '条码',
  `barcode_type` VARCHAR(64) COMMENT '条码类型：EAN13/UPC/INNER',
  `is_primary` TINYINT COMMENT '是否主条码',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='SKU条码';

DROP TABLE IF EXISTS `usr_member`;
CREATE TABLE `usr_member` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '会员ID',
  `register_at` DATETIME COMMENT '注册时间',
  `gender` VARCHAR(64) COMMENT '性别：M/F/U',
  `birth_year` INT COMMENT '出生年份',
  `level_id` BIGINT COMMENT '当前会员等级ID',
  `register_channel_id` BIGINT COMMENT '注册渠道ID',
  `province` VARCHAR(64) COMMENT '常住省份',
  `region_id` BIGINT COMMENT '常住区域ID',
  `member_no` VARCHAR(64) COMMENT '会员编号',
  `nickname` VARCHAR(64) COMMENT '昵称',
  `city` VARCHAR(64) COMMENT '常住城市',
  `phone_masked` VARCHAR(64) COMMENT '手机号（脱敏）',
  `points_balance` INT COMMENT '当前积分余额',
  `total_paid_amount` DECIMAL(14,2) COMMENT '累计实付金额',
  `total_order_cnt` INT COMMENT '累计支付订单数',
  `last_order_at` DATETIME COMMENT '最近下单时间',
  `is_vip_plus` TINYINT COMMENT '是否付费会员',
  `status` VARCHAR(64) COMMENT '状态：ACTIVE/FROZEN/CANCELLED',
  `wechat_bound` TINYINT COMMENT '是否绑定微信',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_level_id` (`level_id`),
  KEY `idx_register_channel_id` (`register_channel_id`),
  KEY `idx_region_id` (`region_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员';

DROP TABLE IF EXISTS `usr_member_level`;
CREATE TABLE `usr_member_level` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '等级ID',
  `name` VARCHAR(64) COMMENT '等级名称：普通/银卡/金卡/黑金',
  `min_points` INT COMMENT '所需积分',
  `discount_rate` DECIMAL(12,6) COMMENT '会员折扣率',
  `benefits` VARCHAR(255) COMMENT '权益说明',
  `free_shipping` TINYINT COMMENT '是否包邮',
  `birthday_coupon` DECIMAL(14,2) COMMENT '生日券面额',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员等级';

DROP TABLE IF EXISTS `usr_member_level_log`;
CREATE TABLE `usr_member_level_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `member_id` BIGINT COMMENT '会员ID',
  `from_level_id` BIGINT COMMENT '原等级',
  `to_level_id` BIGINT COMMENT '新等级',
  `changed_at` DATETIME COMMENT '变更时间',
  `change_type` VARCHAR(64) COMMENT '变更类型：UPGRADE/DOWNGRADE/MANUAL',
  `points_at_change` INT COMMENT '变更时积分',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`),
  KEY `idx_from_level_id` (`from_level_id`),
  KEY `idx_to_level_id` (`to_level_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员等级变更记录';

DROP TABLE IF EXISTS `usr_address`;
CREATE TABLE `usr_address` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '地址ID',
  `member_id` BIGINT COMMENT '会员ID',
  `province` VARCHAR(64) COMMENT '省份',
  `city` VARCHAR(64) COMMENT '城市',
  `is_default` TINYINT COMMENT '是否默认地址',
  `district` VARCHAR(64) COMMENT '区县',
  `detail` VARCHAR(255) COMMENT '详细地址（脱敏）',
  `label` VARCHAR(64) COMMENT '地址标签：HOME/OFFICE/OTHER',
  `created_at` DATETIME COMMENT '创建时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员收货地址簿';

DROP TABLE IF EXISTS `usr_points_log`;
CREATE TABLE `usr_points_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '流水ID',
  `member_id` BIGINT COMMENT '会员ID',
  `change_points` INT COMMENT '积分变动，正为获得负为消耗',
  `biz_type` VARCHAR(64) COMMENT '业务类型：ORDER/REFUND/SIGN_IN/REDEEM',
  `created_at` DATETIME COMMENT '时间',
  `order_id` BIGINT COMMENT '关联订单ID',
  `balance_after` INT COMMENT '变动后余额',
  `expire_at` DATE COMMENT '积分过期日期',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='积分流水';

DROP TABLE IF EXISTS `usr_member_tag`;
CREATE TABLE `usr_member_tag` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `member_id` BIGINT COMMENT '会员ID',
  `tag` VARCHAR(64) COMMENT '标签：HIGH_VALUE高价值/CHURN_RISK流失风险/NEW新客',
  `tag_source` VARCHAR(64) COMMENT '来源：RULE/MODEL/MANUAL',
  `score` DECIMAL(12,6) COMMENT '标签置信分',
  `tagged_at` DATETIME COMMENT '打标时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员标签';

DROP TABLE IF EXISTS `mkt_coupon_template`;
CREATE TABLE `mkt_coupon_template` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `name` VARCHAR(255) COMMENT '券名称',
  `coupon_type` VARCHAR(64) COMMENT '类型：FULL_REDUCTION满减/DISCOUNT折扣/NO_THRESHOLD无门槛',
  `threshold_amount` DECIMAL(14,2) COMMENT '使用门槛金额',
  `face_value` DECIMAL(14,2) COMMENT '面额或折扣',
  `activity_id` BIGINT COMMENT '所属活动ID',
  `valid_days` INT COMMENT '领取后有效天数',
  `total_qty` INT COMMENT '发行总量',
  `per_user_limit` INT COMMENT '每人限领',
  `funded_by` VARCHAR(64) COMMENT '出资方：PLATFORM/MERCHANT/BRAND',
  `scope` VARCHAR(64) COMMENT '适用范围：ALL/CATEGORY/SKU',
  `status` VARCHAR(64) COMMENT '状态：ACTIVE/PAUSED/ENDED',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_activity_id` (`activity_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='优惠券模板';

DROP TABLE IF EXISTS `mkt_coupon`;
CREATE TABLE `mkt_coupon` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '券ID',
  `template_id` BIGINT COMMENT '模板ID',
  `member_id` BIGINT COMMENT '会员ID',
  `status` VARCHAR(64) COMMENT '状态：UNUSED/USED/EXPIRED',
  `received_at` DATETIME COMMENT '领取时间',
  `used_at` DATETIME COMMENT '使用时间',
  `coupon_code` VARCHAR(64) COMMENT '券码',
  `order_id` BIGINT COMMENT '使用的订单ID',
  `expire_at` DATETIME COMMENT '过期时间',
  `receive_channel` VARCHAR(64) COMMENT '领取渠道：ACTIVITY_PAGE/LIVE/CS/AUTO',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_template_id` (`template_id`),
  KEY `idx_member_id` (`member_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户领取的优惠券';

DROP TABLE IF EXISTS `mkt_activity`;
CREATE TABLE `mkt_activity` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '活动ID',
  `name` VARCHAR(255) COMMENT '活动名称，如双11/618/年货节',
  `activity_type` VARCHAR(64) COMMENT '类型：BIG_PROMO大促/FLASH_SALE秒杀/NEW_USER拉新',
  `start_at` DATETIME COMMENT '开始时间',
  `end_at` DATETIME COMMENT '结束时间',
  `budget` DECIMAL(14,2) COMMENT '活动预算',
  `owner` VARCHAR(64) COMMENT '负责人',
  `status` VARCHAR(64) COMMENT '状态：PLANNED/RUNNING/ENDED',
  `target_gmv` DECIMAL(14,2) COMMENT '目标GMV',
  `platform_id` BIGINT COMMENT '平台ID（空为全平台）',
  `description` VARCHAR(255) COMMENT '活动说明',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='营销活动';

DROP TABLE IF EXISTS `mkt_activity_sku`;
CREATE TABLE `mkt_activity_sku` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `activity_id` BIGINT COMMENT '活动ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `activity_price` DECIMAL(14,2) COMMENT '活动价',
  `stock_limit` INT COMMENT '活动库存',
  `per_user_limit` INT COMMENT '每人限购',
  `sold_qty` INT COMMENT '活动已售件数',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_activity_id` (`activity_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='活动商品及活动价';

DROP TABLE IF EXISTS `mkt_channel`;
CREATE TABLE `mkt_channel` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '渠道ID',
  `code` VARCHAR(64) COMMENT '渠道编码：DOUYIN/XHS/BAIDU/WECHAT/ORGANIC',
  `name` VARCHAR(64) COMMENT '渠道名称',
  `is_paid` TINYINT COMMENT '是否付费渠道',
  `owner_team` VARCHAR(64) COMMENT '负责团队',
  `billing_mode` VARCHAR(64) COMMENT '计费方式：CPC/CPM/CPS/FREE',
  `is_active` TINYINT COMMENT '是否启用',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='流量/投放渠道';

DROP TABLE IF EXISTS `mkt_ad_spend`;
CREATE TABLE `mkt_ad_spend` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `stat_date` DATE COMMENT '日期',
  `channel_id` BIGINT COMMENT '渠道ID',
  `spend` DECIMAL(14,2) COMMENT '花费',
  `impressions` BIGINT COMMENT '曝光',
  `clicks` BIGINT COMMENT '点击',
  `campaign_name` VARCHAR(255) COMMENT '投放计划名称',
  `conversions` INT COMMENT '转化数',
  `cpc` DECIMAL(14,2) COMMENT '平均点击成本',
  `account_id` VARCHAR(64) COMMENT '投放账户',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_stat_date` (`stat_date`),
  KEY `idx_channel_id` (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='广告投放花费（按日按渠道）';

DROP TABLE IF EXISTS `mkt_traffic_daily`;
CREATE TABLE `mkt_traffic_daily` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `stat_date` DATE COMMENT '日期',
  `shop_id` BIGINT COMMENT '店铺ID',
  `channel_id` BIGINT COMMENT '渠道ID',
  `pv` BIGINT COMMENT '浏览量',
  `uv` BIGINT COMMENT '访客数',
  `avg_stay_sec` INT COMMENT '平均停留秒数',
  `bounce_rate` DECIMAL(12,6) COMMENT '跳失率',
  `add_cart_uv` INT COMMENT '加购访客数',
  `new_visitor_uv` INT COMMENT '新访客数',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_stat_date` (`stat_date`),
  KEY `idx_shop_id` (`shop_id`),
  KEY `idx_channel_id` (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='店铺流量日表';

DROP TABLE IF EXISTS `mkt_live_session`;
CREATE TABLE `mkt_live_session` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '场次ID',
  `shop_id` BIGINT COMMENT '店铺ID',
  `anchor` VARCHAR(64) COMMENT '主播',
  `start_at` DATETIME COMMENT '开播时间',
  `duration_min` INT COMMENT '时长（分钟）',
  `viewers` INT COMMENT '观看人数',
  `title` VARCHAR(255) COMMENT '直播标题',
  `gmv` DECIMAL(14,2) COMMENT '场次GMV',
  `order_cnt` INT COMMENT '场次订单数',
  `peak_online` INT COMMENT '峰值在线人数',
  `likes` BIGINT COMMENT '点赞数',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_shop_id` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='直播场次';

DROP TABLE IF EXISTS `mkt_member_attribution`;
CREATE TABLE `mkt_member_attribution` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `member_id` BIGINT COMMENT '会员ID',
  `first_order_id` BIGINT COMMENT '首单订单ID',
  `channel_id` BIGINT COMMENT '归因渠道ID',
  `attribution_model` VARCHAR(64) COMMENT '归因模型：FIRST_TOUCH/LAST_TOUCH',
  `attributed_at` DATETIME COMMENT '归因时间',
  `campaign_name` VARCHAR(255) COMMENT '投放计划名称',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`),
  KEY `idx_first_order_id` (`first_order_id`),
  KEY `idx_channel_id` (`channel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员首单归因渠道';

DROP TABLE IF EXISTS `scm_supplier`;
CREATE TABLE `scm_supplier` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '供应商ID',
  `name` VARCHAR(255) COMMENT '供应商名称',
  `province` VARCHAR(64) COMMENT '所在省份',
  `lead_days` INT COMMENT '平均交货周期（天）',
  `supplier_code` VARCHAR(64) COMMENT '供应商编码',
  `contact` VARCHAR(64) COMMENT '联系人',
  `phone_masked` VARCHAR(64) COMMENT '电话（脱敏）',
  `rating` VARCHAR(64) COMMENT '评级：A/B/C/D',
  `settlement_cycle` VARCHAR(64) COMMENT '结算周期：MONTHLY/BIWEEKLY/PER_ORDER',
  `status` VARCHAR(64) COMMENT '状态：ACTIVE/SUSPENDED',
  `credit_limit` DECIMAL(14,2) COMMENT '授信额度',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商';

DROP TABLE IF EXISTS `scm_purchase_order`;
CREATE TABLE `scm_purchase_order` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '采购单ID',
  `supplier_id` BIGINT COMMENT '供应商ID',
  `warehouse_id` BIGINT COMMENT '收货仓ID',
  `status` VARCHAR(64) COMMENT '状态：CREATED/PARTIAL_RECEIVED/RECEIVED/CANCELLED',
  `created_at` DATETIME COMMENT '下单时间',
  `expected_at` DATE COMMENT '预计到货日期',
  `po_no` VARCHAR(64) COMMENT '采购单号',
  `buyer` VARCHAR(64) COMMENT '采购员',
  `total_amount` DECIMAL(14,2) COMMENT '采购总金额',
  `currency_code` VARCHAR(64) COMMENT '币种',
  `approved_at` DATETIME COMMENT '审批时间',
  `received_at` DATETIME COMMENT '实际到货时间',
  `remark` VARCHAR(255) COMMENT '备注',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_supplier_id` (`supplier_id`),
  KEY `idx_warehouse_id` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购单';

DROP TABLE IF EXISTS `scm_purchase_order_item`;
CREATE TABLE `scm_purchase_order_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `po_id` BIGINT COMMENT '采购单ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `quantity` INT COMMENT '采购数量',
  `unit_cost` DECIMAL(14,2) COMMENT '采购单价',
  `received_qty` INT COMMENT '实收数量',
  `tax_rate` DECIMAL(12,6) COMMENT '税率',
  `expected_at` DATE COMMENT '预计到货日期',
  `line_status` VARCHAR(64) COMMENT '行状态：OPEN/RECEIVED/CANCELLED',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_po_id` (`po_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购单明细';

DROP TABLE IF EXISTS `wms_warehouse`;
CREATE TABLE `wms_warehouse` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '仓库ID',
  `name` VARCHAR(64) COMMENT '仓库名称',
  `warehouse_type` VARCHAR(64) COMMENT '类型：CENTRAL中心仓/REGIONAL区域仓/FRONT前置仓',
  `region_id` BIGINT COMMENT '所在区域ID',
  `code` VARCHAR(64) COMMENT '仓库编码',
  `province` VARCHAR(64) COMMENT '所在省份',
  `city` VARCHAR(64) COMMENT '所在城市',
  `area_sqm` INT COMMENT '面积（平方米）',
  `capacity_qty` INT COMMENT '设计容量（件）',
  `manager` VARCHAR(64) COMMENT '仓库负责人',
  `is_bonded` TINYINT COMMENT '是否保税仓',
  `status` VARCHAR(64) COMMENT '状态：ACTIVE/CLOSED',
  `opened_at` DATE COMMENT '启用日期',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_region_id` (`region_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='仓库';

DROP TABLE IF EXISTS `wms_inbound`;
CREATE TABLE `wms_inbound` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '入库单ID',
  `warehouse_id` BIGINT COMMENT '仓库ID',
  `inbound_type` VARCHAR(64) COMMENT '类型：PURCHASE/RETURN/TRANSFER',
  `ref_id` BIGINT COMMENT '来源单据ID（采购单/退款单/调拨单）',
  `received_at` DATETIME COMMENT '入库时间',
  `inbound_no` VARCHAR(64) COMMENT '入库单号',
  `operator` VARCHAR(64) COMMENT '操作员',
  `status` VARCHAR(64) COMMENT '状态：RECEIVING/DONE/CANCELLED',
  `qc_result` VARCHAR(64) COMMENT '质检结果：PASS/PARTIAL/FAIL',
  `dock_no` VARCHAR(64) COMMENT '月台号',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_warehouse_id` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='入库单（采购到货/退货入库/调拨入库）';

DROP TABLE IF EXISTS `wms_inbound_item`;
CREATE TABLE `wms_inbound_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `inbound_id` BIGINT COMMENT '入库单ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `quantity` INT COMMENT '入库数量',
  `expected_qty` INT COMMENT '应收数量',
  `defect_qty` INT COMMENT '次品数量',
  `batch_no` VARCHAR(64) COMMENT '批次号',
  `location_code` VARCHAR(64) COMMENT '上架库位',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_inbound_id` (`inbound_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='入库明细';

DROP TABLE IF EXISTS `wms_inventory_snapshot`;
CREATE TABLE `wms_inventory_snapshot` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `snapshot_date` DATE COMMENT '快照日期',
  `warehouse_id` BIGINT COMMENT '仓库ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `on_hand_qty` INT COMMENT '在库数量',
  `locked_qty` INT COMMENT '已占用数量',
  `available_qty` INT COMMENT '可用数量=在库-占用',
  `in_transit_qty` INT COMMENT '在途数量',
  `defect_qty` INT COMMENT '残次数量',
  `inventory_cost` DECIMAL(14,2) COMMENT '库存成本金额',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_snapshot_date` (`snapshot_date`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='库存日快照：每日24点各仓各SKU库存';

DROP TABLE IF EXISTS `wms_inventory`;
CREATE TABLE `wms_inventory` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `warehouse_id` BIGINT COMMENT '仓库ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `on_hand_qty` INT COMMENT '在库数量',
  `locked_qty` INT COMMENT '已占用数量',
  `safety_stock` INT COMMENT '安全库存',
  `updated_at` DATETIME COMMENT '更新时间',
  `in_transit_qty` INT COMMENT '在途数量',
  `defect_qty` INT COMMENT '残次数量',
  `location_code` VARCHAR(64) COMMENT '主库位',
  `last_inbound_at` DATETIME COMMENT '最近入库时间',
  `last_outbound_at` DATETIME COMMENT '最近出库时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='实时库存：当前时刻各仓各SKU库存';

DROP TABLE IF EXISTS `wms_transfer`;
CREATE TABLE `wms_transfer` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '调拨单ID',
  `from_warehouse_id` BIGINT COMMENT '调出仓',
  `to_warehouse_id` BIGINT COMMENT '调入仓',
  `status` VARCHAR(64) COMMENT '状态：CREATED/IN_TRANSIT/DONE',
  `created_at` DATETIME COMMENT '创建时间',
  `done_at` DATETIME COMMENT '完成时间',
  `transfer_no` VARCHAR(64) COMMENT '调拨单号',
  `reason` VARCHAR(64) COMMENT '调拨原因：REPLENISH/BALANCE/RETURN_TO_CENTRAL',
  `carrier_id` BIGINT COMMENT '承运商ID',
  `operator` VARCHAR(64) COMMENT '操作员',
  `shipped_at` DATETIME COMMENT '发出时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_from_warehouse_id` (`from_warehouse_id`),
  KEY `idx_to_warehouse_id` (`to_warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='调拨单：仓间移库';

DROP TABLE IF EXISTS `wms_transfer_item`;
CREATE TABLE `wms_transfer_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `transfer_id` BIGINT COMMENT '调拨单ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `quantity` INT COMMENT '数量',
  `received_qty` INT COMMENT '实收数量',
  `batch_no` VARCHAR(64) COMMENT '批次号',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_transfer_id` (`transfer_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='调拨明细';

DROP TABLE IF EXISTS `wms_outbound`;
CREATE TABLE `wms_outbound` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '出库单ID',
  `fulfillment_id` BIGINT COMMENT '履约单ID',
  `warehouse_id` BIGINT COMMENT '出库仓ID',
  `picked_at` DATETIME COMMENT '拣货完成时间',
  `outbound_at` DATETIME COMMENT '出库时间',
  `outbound_no` VARCHAR(64) COMMENT '出库单号',
  `picker` VARCHAR(64) COMMENT '拣货员',
  `packer` VARCHAR(64) COMMENT '打包员',
  `package_cnt` TINYINT COMMENT '包裹数',
  `weight_kg` DECIMAL(14,2) COMMENT '包裹重量（千克）',
  `status` VARCHAR(64) COMMENT '状态：PICKING/PACKED/SHIPPED',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_fulfillment_id` (`fulfillment_id`),
  KEY `idx_warehouse_id` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库单：仓库拣货出库';

DROP TABLE IF EXISTS `wms_outbound_item`;
CREATE TABLE `wms_outbound_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `outbound_id` BIGINT COMMENT '出库单ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `quantity` INT COMMENT '出库数量',
  `batch_no` VARCHAR(64) COMMENT '批次号',
  `location_code` VARCHAR(64) COMMENT '拣货库位',
  `picked_qty` INT COMMENT '实拣数量',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_outbound_id` (`outbound_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库明细';

DROP TABLE IF EXISTS `wms_stockout_record`;
CREATE TABLE `wms_stockout_record` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `order_id` BIGINT COMMENT '订单ID',
  `sku_id` BIGINT COMMENT '缺货SKU ID',
  `warehouse_id` BIGINT COMMENT '尝试分配的仓库ID',
  `shortage_qty` INT COMMENT '缺货数量',
  `detected_at` DATETIME COMMENT '发现时间',
  `handle_result` VARCHAR(64) COMMENT '处理结果：CANCELLED/TRANSFERRED/BACKORDERED',
  `handled_at` DATETIME COMMENT '处理时间',
  `alternative_warehouse_id` BIGINT COMMENT '替代仓库ID',
  `notified_buyer` TINYINT COMMENT '是否已通知买家',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_sku_id` (`sku_id`),
  KEY `idx_warehouse_id` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='缺货记录：订单分配库存失败';

DROP TABLE IF EXISTS `wms_stocktake`;
CREATE TABLE `wms_stocktake` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '盘点单ID',
  `warehouse_id` BIGINT COMMENT '仓库ID',
  `stocktake_date` DATE COMMENT '盘点日期',
  `stocktake_no` VARCHAR(64) COMMENT '盘点单号',
  `stocktake_type` VARCHAR(64) COMMENT '盘点类型：FULL/CYCLE/SPOT',
  `operator` VARCHAR(64) COMMENT '盘点人',
  `status` VARCHAR(64) COMMENT '状态：DRAFT/DONE/ADJUSTED',
  `finished_at` DATETIME COMMENT '完成时间',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_warehouse_id` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点单';

DROP TABLE IF EXISTS `wms_stocktake_item`;
CREATE TABLE `wms_stocktake_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `stocktake_id` BIGINT COMMENT '盘点单ID',
  `sku_id` BIGINT COMMENT 'SKU ID',
  `book_qty` INT COMMENT '账面数量',
  `actual_qty` INT COMMENT '实盘数量',
  `diff_qty` INT COMMENT '差异数量=实盘-账面',
  `diff_amount` DECIMAL(14,2) COMMENT '差异金额',
  `location_code` VARCHAR(64) COMMENT '库位',
  `adjust_reason` VARCHAR(64) COMMENT '调整原因：LOSS/DAMAGE/MISPICK/UNKNOWN',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_stocktake_id` (`stocktake_id`),
  KEY `idx_sku_id` (`sku_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='盘点差异明细';

DROP TABLE IF EXISTS `tms_carrier`;
CREATE TABLE `tms_carrier` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '承运商ID',
  `name` VARCHAR(64) COMMENT '名称，如顺丰/京东物流/中通',
  `service_level` VARCHAR(64) COMMENT '服务等级：EXPRESS/STANDARD',
  `code` VARCHAR(64) COMMENT '承运商编码',
  `contact` VARCHAR(64) COMMENT '对接人',
  `contract_end` DATE COMMENT '合同到期日',
  `cod_supported` TINYINT COMMENT '是否支持货到付款',
  `base_fee` DECIMAL(14,2) COMMENT '首重运费',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='承运商（快递公司）';

DROP TABLE IF EXISTS `tms_shipment`;
CREATE TABLE `tms_shipment` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '运单ID',
  `fulfillment_id` BIGINT COMMENT '履约单ID',
  `carrier_id` BIGINT COMMENT '承运商ID',
  `tracking_no` VARCHAR(64) COMMENT '运单号',
  `shipped_at` DATETIME COMMENT '揽收时间',
  `delivered_at` DATETIME COMMENT '签收时间',
  `weight_kg` DECIMAL(14,2) COMMENT '计费重量（千克）',
  `freight_cost` DECIMAL(14,2) COMMENT '运费成本',
  `insured` TINYINT COMMENT '是否保价',
  `receiver_city` VARCHAR(64) COMMENT '收货城市',
  `status` VARCHAR(64) COMMENT '状态：IN_TRANSIT/DELIVERED/EXCEPTION/RETURNED',
  `exception_type` VARCHAR(64) COMMENT '异常类型：DELAY/LOST/DAMAGED/REFUSED',
  `sign_type` VARCHAR(64) COMMENT '签收方式：SELF/AGENT/LOCKER',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_fulfillment_id` (`fulfillment_id`),
  KEY `idx_carrier_id` (`carrier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='发货运单：商家发给用户的快递';

DROP TABLE IF EXISTS `tms_shipment_track`;
CREATE TABLE `tms_shipment_track` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `shipment_id` BIGINT COMMENT '运单ID',
  `node` VARCHAR(64) COMMENT '节点：PICKED_UP/IN_TRANSIT/OUT_FOR_DELIVERY/DELIVERED/EXCEPTION',
  `city` VARCHAR(64) COMMENT '所在城市',
  `event_at` DATETIME COMMENT '时间',
  `description` VARCHAR(255) COMMENT '轨迹描述',
  `operator` VARCHAR(64) COMMENT '网点/快递员',
  `province` VARCHAR(64) COMMENT '所在省份',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_shipment_id` (`shipment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物流轨迹节点';

DROP TABLE IF EXISTS `tms_delivery_sla`;
CREATE TABLE `tms_delivery_sla` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `warehouse_id` BIGINT COMMENT '发货仓ID',
  `region_id` BIGINT COMMENT '收货区域ID',
  `promised_hours` INT COMMENT '承诺送达时长（小时）',
  `carrier_id` BIGINT COMMENT '承运商ID（空为全部）',
  `effective_from` DATE COMMENT '生效日期',
  `service_level` VARCHAR(64) COMMENT '服务等级：EXPRESS/STANDARD',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_region_id` (`region_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='配送时效承诺：按仓库与收货区域';

DROP TABLE IF EXISTS `oms_fulfillment_order`;
CREATE TABLE `oms_fulfillment_order` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '履约单ID',
  `order_id` BIGINT COMMENT '订单ID',
  `warehouse_id` BIGINT COMMENT '分配仓库ID',
  `status` VARCHAR(64) COMMENT '状态：ALLOCATED/PICKING/SHIPPED/DELIVERED/CANCELLED',
  `allocated_at` DATETIME COMMENT '分配时间',
  `promised_at` DATETIME COMMENT '承诺送达时间',
  `fulfillment_no` VARCHAR(64) COMMENT '履约单号',
  `split_seq` TINYINT COMMENT '拆单序号',
  `delivery_type` VARCHAR(64) COMMENT '配送方式：EXPRESS/SAME_DAY/PICKUP',
  `priority` TINYINT COMMENT '优先级1-3',
  `shipped_at` DATETIME COMMENT '发货时间',
  `delivered_at` DATETIME COMMENT '送达时间',
  `cancel_reason` VARCHAR(64) COMMENT '取消原因：STOCKOUT/USER/RISK',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_warehouse_id` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='履约单：订单分配到仓库后的履约任务，一个订单可拆多个';

DROP TABLE IF EXISTS `fin_settlement`;
CREATE TABLE `fin_settlement` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '结算单ID',
  `shop_id` BIGINT COMMENT '店铺ID',
  `month_key` VARCHAR(64) COMMENT '结算月份YYYY-MM',
  `gross_amount` DECIMAL(14,2) COMMENT '应结算总额',
  `commission` DECIMAL(14,2) COMMENT '平台佣金',
  `net_amount` DECIMAL(14,2) COMMENT '实际结算金额',
  `settled_at` DATETIME COMMENT '结算时间',
  `settlement_no` VARCHAR(64) COMMENT '结算单号',
  `refund_deduct` DECIMAL(14,2) COMMENT '退款扣减',
  `freight_income` DECIMAL(14,2) COMMENT '运费收入',
  `adjust_amount` DECIMAL(14,2) COMMENT '调整金额',
  `status` VARCHAR(64) COMMENT '状态：PENDING/CONFIRMED/PAID',
  `invoice_no` VARCHAR(64) COMMENT '结算发票号',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_shop_id` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='店铺结算单（按月）';

DROP TABLE IF EXISTS `fin_settlement_item`;
CREATE TABLE `fin_settlement_item` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '明细ID',
  `settlement_id` BIGINT COMMENT '结算单ID',
  `order_id` BIGINT COMMENT '订单ID',
  `amount` DECIMAL(14,2) COMMENT '结算金额',
  `commission` DECIMAL(14,2) COMMENT '该单佣金',
  `refund_amount` DECIMAL(14,2) COMMENT '该单退款',
  `settle_type` VARCHAR(64) COMMENT '类型：SALE/REFUND/ADJUST',
  `biz_date` DATE COMMENT '业务日期',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_settlement_id` (`settlement_id`),
  KEY `idx_order_id` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='结算明细：按订单';

DROP TABLE IF EXISTS `fin_platform_fee`;
CREATE TABLE `fin_platform_fee` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `platform_id` BIGINT COMMENT '平台ID',
  `category_id` BIGINT COMMENT '一级类目ID',
  `commission_rate` DECIMAL(12,6) COMMENT '佣金率',
  `effective_from` DATE COMMENT '生效日期',
  `effective_to` DATE COMMENT '失效日期',
  `tech_fee_rate` DECIMAL(12,6) COMMENT '技术服务费率',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_platform_id` (`platform_id`),
  KEY `idx_category_id` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='平台费率配置（按平台按类目）';

DROP TABLE IF EXISTS `fin_sales_target`;
CREATE TABLE `fin_sales_target` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `shop_id` BIGINT COMMENT '店铺ID',
  `month_key` VARCHAR(64) COMMENT '月份YYYY-MM',
  `target_amount` DECIMAL(14,2) COMMENT '目标实付金额',
  `target_orders` INT COMMENT '目标订单数',
  `target_gmv` DECIMAL(14,2) COMMENT '目标GMV',
  `owner` VARCHAR(64) COMMENT '负责人',
  `version` VARCHAR(64) COMMENT '目标版本：INITIAL/REVISED',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  `is_deleted` TINYINT COMMENT '逻辑删除标记 1已删除0正常',
  PRIMARY KEY (`id`),
  KEY `idx_shop_id` (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='月度销售目标（按店铺）';

DROP TABLE IF EXISTS `fin_exchange_rate`;
CREATE TABLE `fin_exchange_rate` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `rate_date` DATE COMMENT '日期',
  `currency_code` VARCHAR(64) COMMENT '币种',
  `rate_to_cny` DECIMAL(12,6) COMMENT '兑人民币汇率',
  `source` VARCHAR(64) COMMENT '汇率来源：PBOC/BANK',
  `rate_type` VARCHAR(64) COMMENT '汇率类型：MIDDLE/BUY/SELL',
  `created_by` VARCHAR(64) COMMENT '创建人',
  `created_time` DATETIME COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_currency_code` (`currency_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='汇率（按日）';

DROP TABLE IF EXISTS `dim_region`;
CREATE TABLE `dim_region` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '区域ID',
  `big_region` VARCHAR(64) COMMENT '大区：华东/华北/华南/华中/西南/西北/东北',
  `province` VARCHAR(64) COMMENT '省份',
  `region_code` VARCHAR(64) COMMENT '区域编码',
  `city_tier` VARCHAR(64) COMMENT '城市等级：T1/T2/T3/T4',
  `manager` VARCHAR(64) COMMENT '大区负责人',
  `population_10k` INT COMMENT '人口（万）',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='区域维表：大区-省';

DROP TABLE IF EXISTS `dim_shop`;
CREATE TABLE `dim_shop` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '店铺ID',
  `name` VARCHAR(64) COMMENT '店铺名称',
  `platform_id` BIGINT COMMENT '所属平台ID',
  `region_id` BIGINT COMMENT '运营归属区域ID',
  `opened_at` DATE COMMENT '开店日期',
  `shop_code` VARCHAR(64) COMMENT '店铺编码',
  `shop_type` VARCHAR(64) COMMENT '店铺类型：FLAGSHIP/SPECIALTY/DIRECT',
  `manager` VARCHAR(64) COMMENT '店长',
  `status` VARCHAR(64) COMMENT '状态：OPEN/CLOSED',
  `rating` DECIMAL(12,6) COMMENT '店铺评分',
  `closed_at` DATE COMMENT '关店日期',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_platform_id` (`platform_id`),
  KEY `idx_region_id` (`region_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='店铺维表';

DROP TABLE IF EXISTS `dim_store`;
CREATE TABLE `dim_store` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '门店ID',
  `name` VARCHAR(64) COMMENT '门店名称',
  `shop_id` BIGINT COMMENT '归属店铺ID',
  `region_id` BIGINT COMMENT '所在区域ID',
  `store_code` VARCHAR(64) COMMENT '门店编码',
  `city` VARCHAR(64) COMMENT '所在城市',
  `area_sqm` INT COMMENT '面积（平方米）',
  `opened_at` DATE COMMENT '开业日期',
  `status` VARCHAR(64) COMMENT '状态：OPEN/CLOSED/RENOVATING',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_shop_id` (`shop_id`),
  KEY `idx_region_id` (`region_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='线下门店维表';

DROP TABLE IF EXISTS `dim_date`;
CREATE TABLE `dim_date` (
  `date_key` DATE NOT NULL COMMENT '日期（主键）',
  `year` INT COMMENT '年',
  `quarter` TINYINT COMMENT '季度',
  `month` TINYINT COMMENT '月',
  `week_of_year` TINYINT COMMENT '周',
  `is_weekend` TINYINT COMMENT '是否周末',
  `is_holiday` TINYINT COMMENT '是否法定节假日',
  `promo_name` VARCHAR(64) COMMENT '当日所属大促名称，无则为空',
  `day_of_week` TINYINT COMMENT '星期几1-7',
  `is_workday` TINYINT COMMENT '是否工作日',
  `fiscal_year` INT COMMENT '财年',
  `fiscal_quarter` TINYINT COMMENT '财季',
  `year_month` VARCHAR(64) COMMENT '年月YYYY-MM',
  `week_start` DATE COMMENT '所在周周一日期',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  PRIMARY KEY (`date_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='日期维表';

DROP TABLE IF EXISTS `dim_currency`;
CREATE TABLE `dim_currency` (
  `code` VARCHAR(64) NOT NULL COMMENT '币种代码（主键），如CNY/USD/HKD',
  `name` VARCHAR(64) COMMENT '币种名称',
  `symbol` VARCHAR(64) COMMENT '符号',
  `precision_digits` TINYINT COMMENT '精度位数',
  `is_active` TINYINT COMMENT '是否启用',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  PRIMARY KEY (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='币种维表';

DROP TABLE IF EXISTS `dim_platform`;
CREATE TABLE `dim_platform` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '平台ID',
  `name` VARCHAR(64) COMMENT '平台：天猫/京东/抖音/自营商城',
  `code` VARCHAR(64) COMMENT '平台编码',
  `commission_rate` DECIMAL(12,6) COMMENT '默认佣金率',
  `settle_cycle` VARCHAR(64) COMMENT '结算周期：MONTHLY/BIWEEKLY',
  `is_active` TINYINT COMMENT '是否启用',
  `created_time` DATETIME COMMENT '记录创建时间',
  `updated_time` DATETIME COMMENT '记录更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='销售平台维表';
